"""Check native CPU and worker placement for one Bazel submission."""
from collections import Counter
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import re
import shlex
import subprocess
import sys
import uuid
import xml.etree.ElementTree as ET
from urllib.parse import unquote, urlparse

import exec_cas as cas


W = Path(os.environ["RUNNER_TEMP"]) / "mixed-native"
S = "d41933c9999f4b63085b0cb5211d64dda74bcdc4"
SUBJECTS = {"//pkg/atomicbitops:atomicbitops_test":("oci","TestOrUint32"),
            "//sandboxexec/sandbox:sandbox_test":("firecracker","TestExecNewPIDNamespace")}
CPU = {"amd64":("x86_64",62),"arm64":("aarch64",183)}
T = {l+"_"+c:(c,cls,test) for l,(cls,test) in SUBJECTS.items() for c in CPU}
FILTER = "//runsc/gofer/fs/filter:filter_precompiled"
IMAGE = "docker://docker.io/library/ubuntu@sha256:b8b6ee6aa931ecd9d0d952abc34dc0e5f7c6a30c6bb71b079fe399fde0329c02"
BAZEL = [str(W/"bazel"),"--nosystem_rc","--nohome_rc","--host_jvm_args=-Xmx9500m"]
WRAP = 'echo NATIVE_WORKER=$(/bin/uname -m); echo NATIVE_IDENT=$(/usr/bin/od -An -N4 -tx1 "$1"); echo NATIVE_MACHINE=$(/usr/bin/od -An -j18 -N2 -tu2 "$1"); h=$(/usr/bin/sha256sum "$1"); echo NATIVE_TEST_SHA256=${h%% *}; exec "$@"'
FLAGS = ["--config=source-presubmit-mixed","--color=no","--curses=no","--test_env=GO_TEST_WRAP_TESTV=1",
   "--nocache_test_results","--flaky_test_attempts=1","--modify_execution_info=^(TestRunner|PrecompileSeccomp)$=+no-remote-cache",
   "--run_under="+shlex.join(["/bin/sh","-c",WRAP,"native-cpu"])]
HEX = re.compile(r"[a-f0-9]{64}")
PUB = re.compile(r"//[A-Za-z0-9+._/-]*:[A-Za-z0-9+._/-]+")
GEN = re.compile(r"bazel-out/[A-Za-z0-9._+/-]+/runsc/gofer/fs/filter/filter_precompiled_gen_(?:stubbed|static|dynamic)_bin_/filter_precompiled_gen_(?:stubbed|static|dynamic)_bin$")
TERMS = ("conflicting actions","action conflict","attempted to generate the same","generated by these conflicting","no matching toolchains",
         "no matching execution platform","exec format error","no registered executors","resource_exhausted",
         "resource exhausted","deadline exceeded","operation not permitted","no such file or directory",
         "unknown exec group","permission denied","undeclared inclusion","strict dependencies","out of memory","action failed","signal: killed")


def save(name,d):
    raw=json.dumps(d,sort_keys=True,indent=1)
    assert len(raw)<75000 and not re.search(r"(?i)authorization:|x-buildbuddy-api-key|github_pat_|gh[pousr]_[A-Za-z0-9]{20,}",raw)
    if "ACCESS" in os.environ:assert os.environ["ACCESS"] not in raw
    (W/"output"/(name+".json")).write_text(raw+"\n")


def read(name):
    return json.loads((W/"output"/(name+".json")).read_text())


def events(name):
    p=W/(name+".bep")
    if p.exists():
        with p.open() as f:
            for line in f:
                try:yield json.loads(line)
                except ValueError:return


def signal(path):
    words=set()
    if path.exists():
        with path.open(errors="replace") as f:
            for l in f:
                low=l.lower()
                words.update(t for t in TERMS if t in low)
    return sorted(words)


def call(cmd,phase,args,minutes):
    with (W/(phase+".stdout")).open("w") as out,(W/(phase+".log")).open("w") as err:
        secret=["--bazelrc="+str(W/"remote.rc")] if phase=="execute" else []
        return subprocess.run(["timeout","--signal=INT","--kill-after=45s",str(minutes)+"m",*BAZEL,*secret,cmd,*FLAGS,
                "--build_event_json_file="+str(W/(phase+".bep")),*args],stdout=out,stderr=err).returncode


def analyze():
    src=subprocess.check_output(["git","rev-parse","HEAD"],text=True).strip()
    assert src==S
    assert "remote_default_exec_properties=Arch" not in Path(".bazelrc").read_text()
    # Verify the test suite's public selection before authorizing execution.
    opts=["--spawn_strategy=local","--strategy=TestRunner=local","--jobs=4"]
    code=call("test","selection",[*opts,"--nobuild","--build_tests_only"],11)
    planned=set()
    for e in events("selection"):
        t=e["id"].get("targetCompleted",{})
        if t and not t.get("aspect") and e.get("aborted",{}).get("reason")=="NO_BUILD":
            planned.add(t["label"])
    r={"source":S,"selection_exit":code,"selected":sorted(t for t in planned if PUB.fullmatch(t)),
        "selection_ok":code==1 and planned==T.keys(),"selection_signals":signal(W/"selection.log"),"eligible":False}
    save("selection",r)
    if not r["selection_ok"]:return
    query='let t = set('+" ".join(T)+') in mnemonic("^TestRunner$",$t) union mnemonic("^PrecompileSeccomp$", filter("runsc/gofer/fs/filter:filter_precompiled$",deps($t)))'
    code=call("aquery","graph",[*opts,"--output=jsonproto","--include_artifacts=false","--include_commandline",query],10)
    r.update(graph_exit=code,graph_signals=signal(W/"graph.log"),tests={},generators=[])
    save("selection",r)
    if code:return
    data=json.loads((W/"graph.stdout").read_text());targets={str(t["id"]):t["label"] for t in data["targets"]}
    for a in data.get("actions",[]):
        label=targets[str(a["targetId"])]
        platform=a.get("executionPlatform","").removeprefix("@@")
        arch=next((c for c in CPU if platform=="//tools/bazeldefs:linux_"+c),None)
        if a["mnemonic"]=="TestRunner" and label in T:
            cpu,cls,_=T[label]; p={v["key"]:v.get("value","") for v in a.get("executionInfo",[])}
            isolation=p.get("workload-isolation-type","oci")
            r["tests"][label]={"cpu":arch,"isolation":isolation if isolation in ("oci","firecracker") else "other",
                      "matches":arch==cpu and isolation==cls and (cls!="firecracker" or (p.get("dockerUser")=="root" and p.get("network-enable-ipv6")=="true"))}
        elif a["mnemonic"]=="PrecompileSeccomp" and label==FILTER:
            argv=a.get("arguments",[])
            r["generators"].append({"expected_worker":arch,"argv0":argv[0] if argv and GEN.fullmatch(argv[0]) else None})
    r["eligible"]=r["tests"].keys()==T.keys() and all(t["matches"] for t in r["tests"].values()) and bool(r["generators"]) and all(t["argv0"] and t["expected_worker"] for t in r["generators"])
    save("selection",r)


def execute():
    assert read("selection")["eligible"]
    code=call("test","execute",["--jobs=55","--keep_going","--remote_download_outputs=minimal",
        "--remote_download_regex=.*testlogs/(pkg/atomicbitops/atomicbitops_test_(amd64|arm64)|sandboxexec/sandbox/sandbox_test_(amd64|arm64))/test[.](xml|log)"],42)
    save("exit",{"source":S,"exit":code,"signals":signal(W/"execute.log")})


def output_log(label, output):
    uri=urlparse(output.get("uri",""))
    d=re.search(r"/(?:blobs|compressed-blobs/zstd)/([a-f0-9]{64})/(\d+)$",uri.path)
    ref=(d[1],int(d[2])) if d else (output.get("digest"),int(output.get("length",0)))
    name=output["name"]
    paths=([Path(unquote(uri.path))] if uri.scheme=="file" else [])
    sub=label[2:].replace(":","/")+"/"+name
    paths.extend(Path("bazel-out").glob("*/testlogs/"+sub))
    for p in paths:
        if p.is_file() and p.stat().st_size<=5*1024*1024:
            raw=p.read_bytes();digest=hashlib.sha256(raw).hexdigest()
            if ref[0] and ref!=(digest,len(raw)):continue
            return raw,digest
    return None,None


def collect():
    r={"source":S,"test_results":{},"errors":[],"builds":{},"summaries":{},"verified":False}
    for e in events("execute"):
        ids=e["id"]
        if "started" in e:r["invocation"]=str(uuid.UUID(e["started"]["uuid"]))
        if "finished" in e:r["bazel_exit"]=int(e["finished"].get("exitCode",{}).get("code",0))
        t=ids.get("targetCompleted",{})
        if t.get("label") in T and not t.get("aspect"):
            r["builds"][t["label"]]=e["completed"].get("success",False) if "completed" in e else None
        if "action" in e and not e["action"].get("success",False) and len(r["errors"])<14:
            own=ids.get("actionCompleted",{}).get("label","")
            typ=e["action"].get("type","")
            uri=e["action"].get("stderr",{}).get("uri","")
            d=re.search(r"/blobs/([a-f0-9]{64})/(\d+)$",uri)
            r["errors"].append({"owner":own if PUB.fullmatch(own) else "dependency","mnemonic":typ if re.fullmatch(r"[a-zA-Z0-9_]+",typ) else "other",
                 "stderr":[d[1],int(d[2])] if d else None})
        label=ids.get("testSummary",{}).get("label","")
        if label in T and "testSummary" in e:r["summaries"][label]=e["testSummary"].get("overallStatus")=="PASSED"
        label=ids.get("testResult",{}).get("label","")
        if label not in T or "testResult" not in e:continue
        t=e["testResult"];info=t.get("executionInfo",{});cpu,cls,expected=T[label]
        row={"passed":t.get("status")=="PASSED","remote":info.get("strategy")=="remote",
             "cached":bool(t.get("cachedLocally") or info.get("cachedRemotely")), "expected":expected}
        r["test_results"].setdefault(label,[]).append(row)
        for o in t.get("testActionOutput",[]):
            if o.get("name") not in ("test.log","test.xml"):continue
            raw,digest=output_log(label,o)
            if not raw:continue
            row[o["name"]+"_sha256"]=digest
            if o["name"]=="test.log":
                matches=re.findall(rb"(?m)^NATIVE_WORKER=(aarch64|x86_64)\r?$",raw)
                cpuids=re.findall(rb"(?m)^NATIVE_MACHINE=\s*(62|183)\r?$",raw)
                binary=re.findall(rb"(?m)^NATIVE_TEST_SHA256=([a-f0-9]{64})\r?$",raw)
                row["uname"]=matches[0].decode() if len(matches)==1 else None
                row["machine"]=int(cpuids[0]) if len(cpuids)==1 else None
                row["test_sha256"]=binary[0].decode() if len(binary)==1 else None
                row["elf"]=bool(re.search(rb"(?m)^NATIVE_IDENT=\s*7f 45 4c 46\r?$",raw))
            else:
                try:nodes=list(ET.fromstring(raw).iter("testcase"))
                except ET.ParseError:continue
                counts=Counter();verdict=[]
                for case in nodes:
                    state="passed"
                    if any(case.find(tag) is not None for tag in ("failure","error")):state="failed"
                    elif case.find("skipped") is not None or case.get("status")=="notrun" or case.get("result")=="skipped":state="skipped"
                    counts[state]+=1
                    if case.get("name")==expected:verdict.append(state)
                row["cases"]=dict(counts);row["named_verdict"]=verdict
        row["confirmed"]=row["passed"] and row["remote"] and not row["cached"] and row.get("named_verdict")==["passed"] and row.get("uname")==CPU[cpu][0] and row.get("machine")==CPU[cpu][1] and row.get("elf") is True and bool(row.get("test_sha256"))
    if r["test_results"].keys()==T.keys():
        r["verified"]=r.get("bazel_exit")==0 and all(r["builds"].get(t) and r["summaries"].get(t) and len(r["test_results"][t])==1 and r["test_results"][t][0]["confirmed"] for t in T) and len({r["test_results"][t][0]["test_sha256"] for t in T})==4
    save("test",r)


def platform_fields(message):
    p={}
    for k,v in cas.fields(message):
        if k==1:
            prop=dict(cas.fields(v))
            if 1 in prop and 2 in prop:p[prop[1].decode()]=prop[2].decode()
    return {"cpu":p.get("Arch") if p.get("Arch") in CPU else None,"linux":p.get("OSFamily")=="linux",
        "ubuntu":p.get("container-image")==IMAGE,
        "class":p.get("workload-isolation-type") if p.get("workload-isolation-type") in ("oci","firecracker") else None,
        "root":p.get("dockerUser")=="root","ipv6":p.get("network-enable-ipv6")=="true"}


def input_file(root,path):
    for index,part in enumerate(PurePosixPath(path).parts):
        directory=cas.blob(root,3*1024*1024)
        entries=[dict(cas.fields(v)) for k,v in cas.fields(directory) if k==(1 if index+1==len(PurePosixPath(path).parts) else 2)]
        entry,=[e for e in entries if e.get(1)==part.encode()]
        root=cas.digest_msg(entry[2])
    return cas.native(cas.blob(root,32*1024*1024))


def service():
    test=read("test"); plan=read("selection")
    assert test["source"]==S and plan["source"]==S and plan["eligible"]
    assert subprocess.check_output(["git","rev-parse","HEAD"],text=True).strip()==S
    # Only this workflow's source-bound BEP can select an invocation. No
    # service request is made for any other product or earlier submission.
    cas.INV=str(uuid.UUID(test["invocation"]))
    r={"source":S,"invocation":cas.INV,"workers":{},"producers":[],"diagnostics":{},"verified":False}
    for label in (FILTER,*T):
        try:
            kind="PrecompileSeccomp" if label==FILTER else "TestRunner"
            rows=cas.executions(label,kind)
            assert len(rows)<=15
            for e in rows:
                meta=e["actionDigest"]
                action=dict(cas.fields(cas.blob(meta,128*1024)))
                cmd=list(cas.fields(cas.blob(cas.digest_msg(action[1]),4*1024*1024)))
                args=[v.decode() for t,v in cmd if t==1]
                rep=e.get("executeResponse",{});out=rep.get("result",{})
                if label in T and not (any(s.endswith("/test-setup.sh") for s in args) or
                    any(str(f.get("path","")).endswith("/test.cache_status") for f in out.get("outputFiles",[]))):
                    continue
                p=platform_fields(action[10]) if 10 in action else next((platform_fields(v) for t,v in cmd if t==5),{})
                row={"platform":p,"action_sha256":meta["hash"],"exit":out.get("exitCode",0),"rpc":rep.get("status",{}).get("code",0),
                     "cached":bool(rep.get("cachedResult")),"qemu":any("qemu-" in s for s in args)}
                if label in T:
                    cpu,cls,_=T[label]
                    row["matches"]=p.get("cpu")==cpu and p.get("class")==cls and p.get("linux") and p.get("ubuntu") and (
                        cls!="firecracker" or p.get("root") and p.get("ipv6")) and not row["cached"] and not row["rpc"] and not row["exit"] and not row["qemu"]
                    r["workers"].setdefault(label,[]).append(row)
                else:
                    gen=args[0] if args else ""
                    assert GEN.fullmatch(gen) and ".." not in PurePosixPath(gen).parts
                    assert any(g["argv0"]==gen for g in plan["generators"])
                    row["argv0"]=gen
                    row["configured_worker_matches"]={g["expected_worker"] for g in plan["generators"] if g["argv0"]==gen}=={p.get("cpu")}
                    str_out=[f.get("path","") for f in out.get("outputFiles",[])]
                    row["outputs"]=[s for s in str_out if re.fullmatch(r"bazel-out/[a-zA-Z0-9+_./-]+/runsc/gofer/fs/filter/filter_precompiled[.]go",s)]
                    r["producers"].append(row);save("workers",r)
                    try:
                        row["elf"]=input_file(cas.digest_msg(action[2]),gen)
                        row["identity"]="original-command-input"
                    except (ValueError,AssertionError,KeyError,OSError):
                        # Fetch only this generator's matching GoLink output
                        # from the same invocation and configuration.
                        binary=PurePosixPath(gen).name
                        links=cas.executions(FILTER.rsplit(":",1)[0]+":"+binary,"GoLink")
                        matches={f["digest"]["hash"]:f for l in links for f in l.get("executeResponse",{}).get("result",{}).get("outputFiles",[]) if f.get("path")==gen}
                        if len(matches)==1:
                            row["elf"]=cas.native(cas.blob(next(iter(matches.values()))["digest"],32*1024*1024))
                            row["identity"]="same-invocation-link-exact-path"
                    machine=row.get("elf",{}).get("machine")
                    row["matches"]=row["configured_worker_matches"] and p.get("cpu") in CPU and CPU[p["cpu"]][1]==machine and p.get("linux") and p.get("ubuntu") and p.get("class")=="oci" and not row["cached"] and not row["rpc"] and not row["exit"] and not row["qemu"]
                save("workers",r)
        except (OSError,ValueError,KeyError,AssertionError,IndexError) as ex:
            r["diagnostics"][label]=type(ex).__name__
            save("workers",r)
    seen={p["argv0"] for p in r["producers"] if p.get("matches")}
    r["all_planned_generator_paths_ran"]=bool(seen) and seen=={g["argv0"] for g in plan["generators"]}
    claims={}
    for p in r["producers"]:
        for f in p.get("outputs",[]):claims.setdefault(f,set()).add(p["action_sha256"])
    r["duplicate_generator_output_paths"]=sorted(k for k,v in claims.items() if len(v)>1)
    r["verified"]=(test["verified"] and r["all_planned_generator_paths_ran"] and bool(claims) and not r["duplicate_generator_output_paths"] and
        all(p.get("matches") for p in r["producers"]) and r["workers"].keys()==T.keys() and
        all(any(v["matches"] for v in r["workers"][k]) for k in T))
    save("workers",r)


if __name__=="__main__":
    {"analyze":analyze,"execute":execute,"collect":collect,"service":service}[sys.argv[1]]()
